KG42.register("source_edge_archive-445b631ceafb1c05a242de46",{"id":"05-double_auction::v141-c-R021::E::v141-c-R021-E001","paper":"05-double_auction","rule_id":"v141-c-R021","rule_ref":"05-double_auction::v141-c-R021","record":{"edge_id":"v141-c-R021-E001","source":"matching.counterparties","target":"execution.energy_trade","type":"limits","constraint_ids":["v141-c-R021-C001"],"evidence_ids":["v141-b-g01-ev-08"]},"evidence_class":"S","provenance_gate":"direct_C_edge_with_constraint_and_source_excerpt","scientific_acceptance":false,"accepted_constraint_ids":["v141-c-R021-C001"],"held_constraint_ids":[],"semantic_review_status":"supported","source":"COMP-72f84a438787fbd5","target":"COMP-72f84a438787fbd5","source_occurrence_id":"05-double_auction::v141-c-R021::V::matching.counterparties","target_occurrence_id":"05-double_auction::v141-c-R021::V::execution.energy_trade","source_unit_id":"05-double_auction::v141-a-M04::matching.counterparties","target_unit_id":"05-double_auction::v141-a-M04::execution.energy_trade","omega":{"market_type":"LEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"activation","context_text":"Trade Reduction auction restriction on the buyers and sellers permitted to trade.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-ev-08"]},"active":true,"source_signature":"e57b57e3c8df2655cc05c53d9f8acd44c5bed95658dfe74149f330caa644198d","relation_scope":"original_occurrence_pair_only","internal_to_parent":true,"source_science":{"mechanism_id":"v141-a-M04","source_definition":"Determination of trading counterparties or eligible trading sets in this mechanism: Exclude the marginal gamma buyer/seller pair; gamma-1 pairs trade, buyers paying the marginal bid and sellers receiving the marginal ask.","target_definition":"Contract performance, exchange or delivery conditions in this mechanism: Exclude the marginal gamma buyer/seller pair; gamma-1 pairs trade, buyers paying the marginal bid and sellers receiving the marginal ask.","constraints":[{"constraint_id":"v141-c-R021-C001","kind":"logical","role":"core","statement":"TR counterparty selection limits executed trades to γ − 1 buyers and sellers, excluding buyer γ and seller γ. Scope: Trade Reduction auction restriction on the buyers and sellers permitted to trade.","expression":"|B_TR| = γ − 1 ∧ |S_TR| = γ − 1, where B_TR is the set of buyers permitted to execute trades and S_TR is the set of sellers permitted to execute trades under TR, and buyer γ ∉ B_TR ∧ seller γ ∉ S_TR (γ = largest breakeven buyer-seller index with B_γ^P ≥ S_γ^P)","formalization_origin":"source","template_id":null,"members":["matching.counterparties","execution.energy_trade"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g01-ev-08"]}],"evidence":[{"evidence_id":"v141-b-g01-ev-08","location":{"location_id":"src-22913ad574-p03-c1r2__v141-a-M04-clearing","page":3,"printed_page":null,"section":"2.1","anchor_text":"of trades while maintaining truthful bidding by limiting trades to 1 Ta buyers and sellers [45]. Suc","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-03.png","occurrence_role":"definition"},"source_text":"The Trade Reduction (TR) auction mechanism avoids subsidization of trades while maintaining truthful bidding by limiting trades to $\\gamma - 1$ buyers and sellers [45]. Such differs from uniform k-DA and VCG, where $\\gamma$ buyers and sellers are allowed to transact. Because buyer $\\gamma$ and seller $\\gamma$ are not permitted to participate in the TR auction, social welfare is not maximized. However, trading buyers pay $B_{\\gamma}^P$ and trading sellers receive $S_{\\gamma}^P$. As $B_{\\gamma}^P \\geq S_{\\gamma}^P$, the market operator may financially gain $B_{\\gamma}^P - S_{\\gamma}^P$ from each single unit transaction."}],"omega":{"market_type":"LEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"activation","context_text":"Trade Reduction auction restriction on the buyers and sellers permitted to trade.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-ev-08"]},"source_record":{"edge_id":"v141-c-R021-E001","source":"matching.counterparties","target":"execution.energy_trade","type":"limits","constraint_ids":["v141-c-R021-C001"],"evidence_ids":["v141-b-g01-ev-08"]},"paper_scope_note":"The four auctions are kept separate; the time-period conditions of marginal index, buy/sell eligibility, price bound, shortfall subsidy, and historical price are retained. What is cited is the mechanism description given in the paper and is not expanded to all VCG definitions."}});
